import java.io.*;import java.util.*;import java.util.stream.*;import static java.util.stream.Collectors.toList;class Result {public static int pylons(int k, List<Integer> arr) {int n = arr.size();int count = 0;int i = 0;while (i < n) {int searchEnd = Math.min(i + k - 1, n - 1);int searchStart = Math.max(i - k + 1, 0);int foundIdx = -1;for (int j = searchEnd; j >= searchStart; j--) {if (arr.get(j) == 1) {foundIdx = j;break;}}if (foundIdx == -1) {return -1;}count++;i = foundIdx + k;}return count;}}public class Solution {public static void main(String[] args) throws IOException {BufferedReader bufferedReader = new BufferedReader(new InputStreamReader(System.in));BufferedWriter bufferedWriter = new BufferedWriter(new FileWriter(System.getenv("OUTPUT_PATH")));String[] firstMultipleInput = bufferedReader.readLine().replaceAll("\\s+$", "").split(" ");int n = Integer.parseInt(firstMultipleInput[0]);int k = Integer.parseInt(firstMultipleInput[1]);List<Integer> arr = Stream.of(bufferedReader.readLine().replaceAll("\\s+$", "").split(" ")).map(Integer::parseInt).collect(toList());int result = Result.pylons(k, arr);bufferedWriter.write(String.valueOf(result));bufferedWriter.newLine();bufferedReader.close();bufferedWriter.close();}}